(function(){
'use strict';
const D=window.OuroData,E=window.OuroEngine,G=window.OuroGoalsView,B=window.OuroBookView,KEY='onze-de-ouro-save-v1',PREF='onze-de-ouro-prefs-v1',LEGACY_KEY='xi-e-craque-legends-v1',BOOK_KEY='xi-e-craque-club-book-v1';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>Math.round(x||0).toLocaleString('pt-BR'),money=x=>`<span class="coin-dot" aria-hidden="true">$</span> ${n(x)}`;
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',cards:'m7 3 13 3-4 16L3 19Zm3-2 11 4m-9 3 3 .7m-4 3 3 .7',trophy:'M8 21h8m-4-4v4M7 3h10v7a5 5 0 0 1-10 0Zm0 2H4v3a4 4 0 0 0 4 4m9-7h3v3a4 4 0 0 1-4 4',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',play:'m8 5 11 7-11 7Z',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7Zm-4 9 3 3 5-5',bolt:'m13 2-9 12h7l-1 8 10-13h-7Z',target:'M21 12a9 9 0 1 1-9-9m0 4a5 5 0 1 0 5 5m-5 0 9-9m-5 0h5v5',chart:'M4 20V10m8 10V4m8 16v-7M2 22h20',news:'M4 3h14v18H4Zm3 4h8m-8 4h8m-8 4h5M18 8h3v11a2 2 0 0 1-2 2',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',share:'M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6m0 14a3 3 0 1 0 0-6 3 3 0 0 0 0 6M6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6m2-4 7-4m-7 6 7 4',help:'M9 9a3 3 0 1 1 5 2.2c-1.2.8-2 1.2-2 2.8m0 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',volume:'m11 5-6 4H2v6h3l6 4Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',lock:'M5 10h14v11H5Zm3 0V6a4 4 0 0 1 8 0v4',swap:'M3 7h16m-4-4 4 4-4 4M21 17H5m4-4-4 4 4 4',refresh:'M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 14 6M4 12a8 8 0 0 0 14 6',calendar:'M4 5h16v16H4Zm3-3v6m10-6v6M4 11h16',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14m5-2 6 6'};
function icon(key,extra=''){return `<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[key]||icons.star}"></path></svg>`;}
let state=null,view='club',squadTab='pitch',leagueTab='table',leagueRound=0,rosterFilter='',rosterPos='all',rosterSort='ovr',modalType='',matchTimer=null,matchMinute=90,toastTimer=null,savingOK=true;
let prefs={sound:false,quick:false};try{prefs={...prefs,...JSON.parse(localStorage.getItem(PREF)||'{}')};const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(E.validate(parsed))state=parsed;else window.saveCorrupted=true;}}catch{window.saveCorrupted=true;}
let legacyProfile={version:1,unlocked:false,card:null};try{const loaded=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null');if(E.validLegacyProfile(loaded))legacyProfile=loaded;}catch{}
if(state){E.updateCareerGoals(state);legacyProfile=E.unlockLegacyProfile(legacyProfile,state);}
let clubBook=E.newClubBook();try{const loaded=JSON.parse(localStorage.getItem(BOOK_KEY)||'null');if(loaded){if(!E.validClubBook(loaded))throw Error('Memórias inválidas');clubBook=loaded;}}catch{window.bookCorrupted=true;}
if(state){E.ensureClubLore(state);E.updateNicknames(state);}
let careerTab='current',albumFilters={query:'',status:'all',rarity:'all',pos:'all'},albumPage=0,hallSort='titles';
let captainOptions=E.drawCaptains();
let draft={name:'',short:'',color:'#bcf269',secondary:'#172b24',starter:'balanced',captain:captainOptions[0],slot:'bot',careerGoals:[],rival:'fla'};
const app=$('#app'),modal=$('#modal');
function syncLegacyProfile(){try{const stored=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null');if(E.validLegacyProfile(stored))legacyProfile={version:1,unlocked:legacyProfile.unlocked||stored.unlocked,card:legacyProfile.card||stored.card};}catch{}}
function syncBook(){const stored=JSON.parse(localStorage.getItem(BOOK_KEY)||'null');if(stored){if(!E.validClubBook(stored))throw Error('Não foi possível ler suas memórias salvas.');clubBook=E.mergeClubBooks(stored,clubBook);}if(state){const result=E.syncClubBook(clubBook,state);clubBook=result.book;if(result.archived&&result.newRecords.length)state.news.unshift({title:'Novo recorde do professor!',text:result.newRecords.map(id=>E.hallRecordDefinitions.find(r=>r.id===id).name).join(' · ')+'. Veja seu Hall da Fama na aba Carreira.',kind:'record',season:5,round:19});}}
function save(){try{const earned=E.updateCareerGoals(state);syncLegacyProfile();legacyProfile=E.unlockLegacyProfile(legacyProfile,state);localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(LEGACY_KEY,JSON.stringify(legacyProfile));syncBook();localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(BOOK_KEY,JSON.stringify(clubBook));savingOK=true;$('.saving-warning')?.remove();if(earned.length)toast('Novo selo conquistado! Veja seu legado na aba Carreira.');}catch{savingOK=false;if(!$('.saving-warning'))document.body.insertAdjacentHTML('beforeend','<div class="saving-warning">Não foi possível salvar todo o progresso neste navegador. Exporte seu backup em Configurações antes de sair.</div>');}}
function bookContent(){return careerTab==='hall'?B.hall(clubBook,state,hallSort,badge):B.album(clubBook,albumFilters,albumPage,card);}
function renderMemories(){app.innerHTML=`<main id="main" class="memory-page"><header class="memory-top"><div class="brand"><b class="brand-mark">XI</b><span class="brand-name">É<br>CRAQUE</span></div><button class="btn secondary small" data-action="back-setup">← Criar meu clube</button></header>${heading('Seu futebol fica na memória','Um álbum. Muitas histórias.','Seu álbum e suas carreiras completas continuam por aqui.')}${B.tabs(careerTab,false)}${bookContent()}<div class="actions"><button class="btn secondary small" data-action="export">Exportar memórias</button><button class="btn ghost small" data-action="import">Importar backup</button></div></main>`;}
function refreshAlbum(){const container=$('#album-results');if(container)container.innerHTML=B.albumResults(clubBook,albumFilters,albumPage,card);}
function refreshRivalSetup(){if(draft.rival===draft.slot)draft.rival=D.teams.find(t=>t.id!==draft.slot).id;const node=$('#rival-setup');if(node)node.outerHTML=B.setupRival(draft);}
function refreshGoalSetup(){const node=$('#career-goal-picker');if(node)node.outerHTML=G.setup(draft.careerGoals,legacyProfile);}
function showGoalPicker(keepScroll=false,focusId=''){const scroll=keepScroll?modal.scrollTop:0;openModal(G.picker(draft.careerGoals,legacyProfile),'goals','goals-dialog');requestAnimationFrame(()=>{if(keepScroll)modal.scrollTop=scroll;if(focusId)modal.querySelector(`[data-id="${focusId}"]`)?.focus({preventScroll:true});});}
function previewLegacy(){const form=$('#legacy-form');if(!form)return;const input=Object.fromEntries(new FormData(form));try{$('#legacy-preview').innerHTML=card(E.makeLegacyCard({...input,name:input.name.trim().length>=2?input.name:'Meu Craque'},'legacy-preview'));}catch{}}
function savePrefs(){try{localStorage.setItem(PREF,JSON.stringify(prefs));}catch{}}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('toast-show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('toast-show'),3400);}
function sound(kind='click'){if(!prefs.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ctx=sound.ctx||(sound.ctx=new AC());ctx.resume();const notes=kind==='pack'?[261.63,329.63,392,523.25]:kind==='win'?[392,523.25,659.25]:[440];notes.forEach((f,i)=>{let o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=f;o.connect(g);g.connect(ctx.destination);const t=ctx.currentTime+i*.1;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.05,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.35);o.start(t);o.stop(t+.36);});}catch{}}
function badge(t,size=''){const shape=['shield','round','diamond','banner'].includes(t.crestShape)?t.crestShape:'shield',pattern=['split','stripe','bands','dots','solid'].includes(t.crestPattern)?t.crestPattern:'split',mark=['star','ball','bolt','crown','none'].includes(t.crestMark)?t.crestMark:'star',showLabel=t.crestShowLabel!==false,labelColor=/^#[a-f\d]{6}$/i.test(t.crestLabelColor)?t.crestLabelColor:'#ffffff';return `<span class="crest ${size}" data-crest-shape="${shape}" data-crest-pattern="${pattern}" data-crest-mark="${mark}" data-crest-show-label="${showLabel}" data-crest-label-color="${labelColor}" style="--crest-color:${/^#[a-f\d]{6}$/i.test(t.color)?t.color:'#bcf269'};--crest-secondary:${/^#[a-f\d]{6}$/i.test(t.secondary)?t.secondary:'#1b242b'}" aria-hidden="true">${esc(t.short||t.name.slice(0,3).toUpperCase())}</span>`;}
function initials(p){return p.name.replace(/Jr\.|Júnior/g,'J').split(/[ .-]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('');}
function card(p,cls=''){return `<div class="player-card ${E.tier(p)} ${cls}" aria-label="${esc(p.name)}, ${p.pos}, overall ${p.ovr}${p.special==='totw'?', Time da Semana':p.special==='legacy'?', Lenda do clube':''}"><div class="card-top"><div><div class="card-rating">${p.ovr}</div><div class="card-pos">${p.pos}</div></div><span class="card-country" title="${esc(D.nations[p.nation]||p.nation)}">${p.nation}${p.special==='totw'?`<b class="card-boost">+${p.ovr-(D.byId[p.baseId]?.ovr||p.ovr)}</b>`:''}</span></div><div class="card-monogram" data-avatar-seed="${esc(p.name)}" aria-hidden="true">${esc(initials(p))}</div><div class="card-name">${esc(p.name)}</div><div class="card-stats"><span><b>${p.vel}</b> VEL</span><span><b>${p.def}</b> DEF</span><span><b>${p.fin}</b> FIN</span><span><b>${p.fis}</b> FÍS</span><span><b>${p.pas}</b> PAS</span><span><b>${p.gol}</b> GOL</span></div><div class="card-edition">${p.special==='legacy'?'LENDA DO CLUBE':p.special==='totw'?'TIME DA SEMANA':p.ovr>=88?'SELEÇÃO DE ELITE':'XI, É CRAQUE'}</div></div>`;}
function mini(p,slot,cap=false){return `<div class="mini-card ${E.tier(p)}">${cap?'<span class="captain-badge" title="Capitão">C</span>':''}${slot&&E.fit(p,slot)<.9?'<span class="out-position" title="Fora da posição ideal">!</span>':''}<div class="mini-rating"><b>${p.ovr}</b><span>${p.pos}</span></div><div class="mini-monogram" data-avatar-seed="${esc(p.name)}" aria-hidden="true">${esc(initials(p))}</div><div class="mini-name">${esc(p.name)}</div></div>`;}
function packet(p){return `<div class="packet ${p.tier}" aria-hidden="true"><span class="packet-logo">XI</span><span class="packet-name">${esc(p.name)}</span><span class="packet-min">${p.max?`${p.min}–${p.max}`:p.min+'+'}</span>${p.mode==='choice'?'<span class="packet-extra">ESCOLHA 1 DE 3</span>':p.id==='totw'?'<span class="packet-extra">'+esc(D.weekly.label)+'</span>':''}</div>`;}
function coins(v){return `<span class="gold-text">${money(v)}</span>`;}
function progress(v,max){return `<div class="progress" role="progressbar" aria-valuenow="${Math.min(v,max)}" aria-valuemin="0" aria-valuemax="${max}"><i style="width:${Math.min(100,v/max*100)}%"></i></div>`;}
function formDots(row){return `<span class="form-dots">${Array(Math.max(0,5-row.form.length)).fill('<i class="form-dot blank">·</i>').join('')}${row.form.slice(-5).map(v=>`<i class="form-dot ${v}" title="${{V:'Vitória',E:'Empate',D:'Derrota'}[v]}">${v}</i>`).join('')}</span>`;}
function render(){if(!state){if(view==='memories')renderMemories();else renderSetup();return;}document.documentElement.style.setProperty('--club',state.club.color);E.updateObjectives(state);const nav=[['club','home','Meu clube'],['squad','users','Elenco'],['packs','cards','Pacotes'],['league','trophy','Liga'],['career','chart','Carreira']];
 app.innerHTML=`<aside class="sidebar"><div class="brand"><b class="brand-mark">XI</b><span class="brand-name">É<br>CRAQUE</span></div><nav aria-label="Navegação principal">${nav.map(([id,ic,label])=>`<button class="nav-item ${view===id?'active':''}" data-action="nav" data-view="${id}" aria-label="${label}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='packs'&&state.pendingPack?'<span class="badge">1</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="eyebrow">Sua trajetória</div><strong>Temporada ${state.season} de 5</strong><div class="season-rail">${[1,2,3,4,5].map(i=>`<span class="${i<=state.season?'done':''}"></span>`).join('')}</div><p>Um clube. Cinco chances de fazer história.</p><button class="text-button" data-action="help">Como jogar</button></div></aside><div class="shell"><header class="topbar"><div class="club-identity">${badge(state.club)}<div><strong>${esc(state.club.name)}</strong><small>Temporada ${state.season} <span aria-hidden="true">·</span> ${state.phase==='finished'?'Carreira concluída':state.phase==='seasonEnd'?'Temporada encerrada':`Rodada ${Math.min(state.round+1,19)} de 19`}</small></div></div><div class="actions"><div class="coin-balance" aria-label="${state.coins} moedas">${money(state.coins)}</div><button class="icon-btn" data-action="settings" aria-label="Configurações">${icon('settings')}</button></div></header><main class="main" id="main" tabindex="-1">${view==='club'?dashboard():view==='squad'?squad():view==='packs'?shop():view==='league'?league():career()}</main></div><nav class="bottom-nav" aria-label="Navegação móvel">${nav.map(([id,ic,label])=>`<button class="${view===id?'active':''}" data-action="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${id==='club'?'Clube':label}</span></button>`).join('')}</nav>`;
 if(view==='career'&&state.phase==='finished')requestAnimationFrame(()=>drawFinal($('#career-canvas')));
}
function renderSetup(){app.innerHTML=`<main id="main" class="start-page"><header class="start-top"><div class="brand"><b class="brand-mark">XI</b><span class="brand-name">É<br>CRAQUE</span></div><span class="small">Futebol. Cartas. Sua história.</span></header><div class="start-grid"><section class="start-intro"><div class="eyebrow">A próxima grande história é sua</div><h1>XI,<br><em>é Craque</em></h1><p>Revele craques, encontre o time ideal e transforme cinco temporadas em uma carreira inesquecível.</p><div class="start-showcase">${card(D.byId[draft.captain])}${packet(D.packs[0])}</div><div class="start-proof"><div><strong>20 clubes</strong><small>Uma liga para conquistar</small></div><div><strong>${D.players.length} cartas</strong><small>Seu próximo reforço</small></div><div><strong>5 temporadas</strong><small>Um legado para criar</small></div></div><div class="start-memories"><button class="btn secondary small" data-action="open-memories" data-tab="album">Meu álbum permanente</button><button class="btn ghost small" data-action="open-memories" data-tab="hall">Hall da Fama</button></div></section><section class="create-panel"><h2>Monte a identidade do clube</h2><form id="create-form"><div class="fields"><label class="field"><span>Nome do clube</span><input name="clubName" id="club-name" placeholder="Ex.: Resenha FC" maxlength="26" minlength="2" value="${esc(draft.name)}" required autocomplete="off"></label><label class="field"><span>Sigla</span><input name="short" id="club-short" placeholder="RFC" maxlength="3" pattern="[A-Za-z0-9]{2,3}" value="${esc(draft.short)}" required autocomplete="off" style="text-transform:uppercase" title="Use 2 ou 3 letras ou números"></label></div><div class="color-fields"><label class="color-field"><input type="color" name="primary" value="${draft.color}" aria-label="Cor principal"><span>Principal</span></label><label class="color-field"><input type="color" name="secondary" value="${draft.secondary}" aria-label="Cor secundária"><span>Secundária</span></label></div><span class="setup-label" id="starter-label">Escolha a base do elenco</span><div class="starter-options" role="group" aria-labelledby="starter-label">${[['balanced','Equilibrado','shield'],['attack','Ofensivo','bolt'],['defense','Defensivo','lock']].map(([id,label,ic])=>`<button type="button" class="starter-option ${draft.starter===id?'active':''}" data-action="starter" data-id="${id}" aria-pressed="${draft.starter===id}">${icon(ic)}<strong>${label}</strong></button>`).join('')}</div><span class="setup-label" id="captain-label">Quem vai vestir a faixa?</span><div class="captain-options" role="group" aria-labelledby="captain-label">${captainOptions.map(id=>{let p=D.byId[id];return `<button type="button" class="captain-option ${draft.captain===id?'active':''}" data-action="captain-draft" data-id="${id}" aria-pressed="${draft.captain===id}"><span class="captain-ovr">${p.ovr}</span><span><strong>${esc(p.name)}</strong><small>${p.pos} · ${p.nation}</small></span></button>`;}).join('')}</div><p class="captain-help">Seis jogadores sorteados a cada nova carreira.</p><button class="btn secondary small reroll-captains" type="button" data-action="reroll-captains">Sortear outros capitães</button><div class="setup-slot"><label for="club-slot">Seu clube entra na vaga de</label><select id="club-slot" name="slot">${D.teams.map(t=>`<option value="${t.id}" ${draft.slot===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><small>Seu clube + 19 adversários brasileiros. Turno único, sem rebaixamento.</small></div>${B.setupRival(draft)}${G.setup(draft.careerGoals,legacyProfile)}<button class="btn wide" type="submit">Criar clube e abrir meu pacote ${icon('cards')}</button><p class="setup-note">18 jogadores iniciais + pacote gratuito com um jogador 80+.</p>${window.saveCorrupted?'<p class="inline-error">Não foi possível ler o progresso anterior. Você pode importar um backup ou começar outra carreira.</p><button type="button" class="text-button" data-action="import">Importar progresso</button>':''}</form></section></div><footer class="start-footer">Seu progresso fica salvo neste navegador. Jogue no seu ritmo.</footer></main>`;}
function heading(eyebrow,title,desc='',action=''){return `<div class="page-heading ${action?'space':''}"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function statBoxes(items){return `<div class="stat-grid">${items.map(([v,l,c])=>`<div class="stat-box"><div class="value ${c||''}">${v}</div><div class="label">${l}</div></div>`).join('')}</div>`;}
function dashboard(){let table=E.ranked(state),row=table.find(t=>t.id==='user'),rank=table.indexOf(row)+1,m=E.metrics(E.team(state,'user')),next=E.preview(state);return `${heading('Central do clube','O jogo começa aqui.',state.phase==='active'?'O próximo reforço. A próxima vitória. Sua próxima decisão.':'Mais um capítulo para a história do seu clube.')} ${statBoxes([[state.round?rank+'º':'—','Na classificação'],[row.pts,'Pontos'],[m.overall,'Força do time','lime-text'],[row.gf,'Gols marcados']])}${B.rivalry(state,badge)}<div class="dashboard-grid">${next?`<section class="panel fixture-panel"><div class="space"><span class="eyebrow">${E.isDerby(state,next.fixture)?'É dia de clássico!':'Próxima partida'}</span><span class="chip">RODADA ${state.round+1}</span></div><div class="fixture-teams"><div class="fixture-team">${badge(next.home,'large')}<strong>${esc(next.home.name)}</strong><span class="small muted">Mandante</span></div><div class="vs">VS</div><div class="fixture-team">${badge(next.away,'large')}<strong>${esc(next.away.name)}</strong><span class="small muted">Visitante</span></div></div><div class="fixture-details"><span>Liga brasileira</span><span>•</span><span>Temporada ${state.season}</span></div><div class="fixture-bottom"><div><small class="muted">Chance de vitória <strong class="lime-text">${next.win}%</strong></small><div class="prob-bar" aria-hidden="true"><span style="width:${next.win}%"></span><span style="width:${next.draw}%"></span><span style="width:${next.loss}%"></span></div></div><button class="btn" data-action="prematch">${icon('play')} Jogar partida</button></div></section>`:`<section class="panel fixture-panel"><span class="eyebrow">${state.phase==='finished'?'Carreira concluída':'Apito final'}</span><div class="fixture-teams"><div class="fixture-team">${badge(state.history.at(-1).champion,'large')}<strong>${esc(state.history.at(-1).champion.name)}</strong></div><div class="vs">${icon('trophy')}</div><div class="fixture-team"><strong class="gold-text" style="font-size:2.7rem">${state.history.at(-1).position}º</strong><span class="small">Sua colocação</span></div></div><p>O campeão foi definido. Veja os destaques e a avaliação do seu trabalho.</p><div class="fixture-bottom"><span class="small muted">Temporada ${state.season} encerrada</span><button class="btn" data-action="season-summary">Ver temporada</button></div></section>`}<section class="panel promo"><div><span class="eyebrow gold-text">${state.pendingPack?'Pacote esperando':'Mercado de talentos'}</span><h2>O próximo craque pode ser seu.</h2><p>${state.pendingPack?'Seu pacote já está garantido. Continue a revelação.':'Abra um pacote e encontre a peça que falta no seu time.'}</p></div>${packet(D.packs.find(p=>p.id==='gold'))}<button class="btn" data-action="${state.pendingPack?'resume-pack':'nav'}" data-view="packs">${icon('cards')} ${state.pendingPack?'Revelar cartas':'Ver pacotes'}</button></section></div>${G.summary(state,true)}<div class="lower-grid"><section class="panel"><div class="panel-heading"><h2>Objetivos da temporada</h2>${icon('target')}</div>${objectives()}</section><section class="panel"><div class="panel-heading"><h2>Na briga pela taça</h2><button class="text-button" data-action="nav" data-view="league">Ver liga</button></div>${miniTable()}${state.lastMatch?`<div class="rule"></div><div class="space"><span class="small muted">Última partida</span><button class="text-button" data-action="last-match">Ver resultado</button></div>`:''}</section></div><section class="panel" style="margin-top:22px"><div class="panel-heading"><h2>Voz da arquibancada</h2>${icon('news')}</div>${news(3)}</section>`;}
function objectives(){return state.objectives.map(o=>`<div class="objective"><div class="space"><div><h3>${esc(o.title)}</h3><p>${esc(o.detail)}</p></div>${o.claimed?`<span class="chip">${icon('check')} Recebido</span>`:o.progress>=o.target?`<button class="btn small" data-action="claim" data-id="${o.id}">Receber ${n(o.reward)}</button>`:`<span class="reward">+ ${n(o.reward)} $</span>`}</div>${progress(o.progress,o.target)}<div class="space" style="margin-top:6px"><small class="muted">${Math.min(o.progress,o.target)} / ${o.target}</small>${o.claimed?'<small class="muted">Concluído</small>':''}</div></div>`).join('');}
function miniTable(){const table=E.ranked(state),rows=table.slice(0,4);if(!rows.some(t=>t.id==='user'))rows.push(table.find(t=>t.id==='user'));return `<div class="table-wrap"><table class="mini-table"><thead><tr><th>Pos.</th><th>Clube</th><th class="numeric">J</th><th class="numeric">PTS</th></tr></thead><tbody>${rows.map(t=>`<tr class="${t.id==='user'?'user-row':''}"><td class="table-rank">${table.indexOf(t)+1}</td><td><span class="table-team">${badge(E.team(state,t.id),'tiny')}${esc(E.team(state,t.id).name)}</span></td><td class="numeric">${t.played}</td><td class="numeric"><strong>${t.pts}</strong></td></tr>`).join('')}</tbody></table></div>`;}
function news(count=40){return state.news.slice(0,count).map(x=>`<article class="news-item"><span class="news-icon">${icon(x.kind==='trophy'?'trophy':x.kind==='transfer'?'cards':x.kind==='match'?'bolt':'news')}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p><small>Temporada ${x.season} · ${x.round?'Após a rodada '+x.round:'Pré-temporada'}</small></div></article>`).join('');}
function squad(){const t=E.team(state,'user'),m=E.metrics(t),f=D.formations[state.formation];return `${heading('Vestiário','Cada peça faz a diferença.',`${state.squad.length} jogadores no clube · toque em um titular para trocar.`,state.phase!=='finished'?'<button class="btn secondary" data-action="auto-lineup">'+icon('bolt')+' Melhor escalação</button>':'')}<div class="subtabs"><button class="${squadTab==='pitch'?'active':''}" data-action="squad-tab" data-tab="pitch">Escalação</button><button class="${squadTab==='cards'?'active':''}" data-action="squad-tab" data-tab="cards">Minhas cartas (${state.squad.length})</button><button class="${squadTab==='stats'?'active':''}" data-action="squad-tab" data-tab="stats">Desempenho</button></div>${squadTab==='cards'?roster():squadTab==='stats'?squadStats():`<div class="squad-layout"><section class="pitch-panel"><div class="pitch-toolbar"><label for="formation" class="eyebrow">Time titular</label><select id="formation" aria-label="Formação" ${state.phase==='finished'?'disabled':''}>${Object.keys(D.formations).map(v=>`<option ${state.formation===v?'selected':''}>${v}</option>`).join('')}</select><span class="chip">${m.overall} OVR</span></div><div class="pitch" aria-label="Escalação em campo"><div class="pitch-lines"><div class="pitch-circle"></div><div class="penalty top"></div><div class="penalty bottom"></div></div>${f.map(([pos,x,y],i)=>`<button class="pitch-player" style="left:${x}%;top:${y}%" data-action="pick-slot" data-slot="${i}" aria-label="${pos}: ${esc(D.byId[state.lineup[i]].name)}, ${D.byId[state.lineup[i]].ovr}. Trocar jogador">${mini(D.byId[state.lineup[i]],pos,state.captain===state.lineup[i])}<span class="slot-label">${pos}</span></button>`).join('')}</div><div class="bench-title"><h3>Banco de reservas</h3><small class="muted">Até 3 substituições automáticas</small></div><div class="bench">${state.bench.map(id=>`<button data-action="bench-picker" data-id="${id}" aria-label="Reserva ${esc(D.byId[id].name)}. Trocar reserva">${mini(D.byId[id])}</button>`).join('')}</div></section><aside class="stack squad-side"><section class="panel"><div class="panel-heading"><h2>Força por setor</h2>${icon('chart')}</div><div class="metrics"><div class="metric"><strong>${Math.round(m.attack)}</strong><small>Ataque</small></div><div class="metric"><strong>${Math.round(m.mid)}</strong><small>Meio</small></div><div class="metric"><strong>${Math.round(m.defense)}</strong><small>Defesa</small></div></div><div class="space" style="margin:17px 0 8px"><span class="small muted">Adequação às posições</span><strong class="small ${m.fit<90?'gold-text':'lime-text'}">${m.fit}%</strong></div>${progress(m.fit,100)}<p class="squad-tip">${m.fit<95?'O símbolo ! indica uma adaptação com perda de rendimento. Troque o jogador ou a formação.':'Seu time está bem distribuído. Compare os setores antes de definir a estratégia.'}</p><div class="rule"></div><label class="field"><span>Capitão</span><select id="captain-select" ${state.phase==='finished'?'disabled':''}>${state.lineup.map(id=>`<option value="${id}" ${id===state.captain?'selected':''}>${esc(D.byId[id].name)}</option>`).join('')}</select></label><p class="squad-tip">A faixa dá um pequeno bônus coletivo quando o capitão está em campo.</p></section><section class="panel"><h2>Plano de jogo</h2><div class="tactic-list">${Object.entries(D.tactics).map(([id,v])=>`<button class="tactic-option ${state.tactic===id?'active':''}" data-action="tactic" data-id="${id}" ${state.phase==='finished'?'disabled':''} aria-pressed="${state.tactic===id}"><strong>${state.tactic===id?icon('check'):''}${v.name}</strong><p>${v.description}</p></button>`).join('')}</div></section></aside></div>`}`;}
function roster(){return `<div class="roster-tools"><input type="search" id="roster-search" placeholder="Buscar jogador…" aria-label="Buscar jogador no elenco" value="${esc(rosterFilter)}"><select id="roster-position" aria-label="Filtrar posição"><option value="all">Todas as posições</option>${[...new Set(D.players.map(p=>p.pos))].map(pos=>`<option ${rosterPos===pos?'selected':''}>${pos}</option>`).join('')}</select><select id="roster-sort" aria-label="Ordenar cartas"><option value="ovr" ${rosterSort==='ovr'?'selected':''}>Maior overall</option><option value="name" ${rosterSort==='name'?'selected':''}>Nome</option><option value="value" ${rosterSort==='value'?'selected':''}>Maior valor</option></select></div><div id="roster-cards">${rosterCards()}</div>`;}
function rosterCards(){const players=state.squad.map(id=>D.byId[id]).filter(p=>(rosterPos==='all'||p.pos===rosterPos)&&p.name.toLowerCase().includes(rosterFilter.toLowerCase())).sort((a,b)=>rosterSort==='name'?a.name.localeCompare(b.name):rosterSort==='value'?E.value(b)-E.value(a):b.ovr-a.ovr);return players.length?`<div class="card-grid">${players.map(p=>`<article class="roster-card"><button data-action="player" data-id="${p.id}" aria-label="Detalhes de ${esc(p.name)}">${card(p)}</button>${B.nickTag(state,p.id)}<div class="roster-status">${state.captain===p.id?'<span class="in">Capitão</span>':state.lineup.includes(p.id)?'<span class="in">Titular</span>':state.bench.includes(p.id)?'Reserva':'No clube'}<span>·</span><span>${n(E.value(p))} $</span></div></article>`).join('')}</div>`:'<div class="empty">Nenhum jogador encontrado com esse filtro.</div>';}
function squadStats(){const stats=Object.values(state.stats).filter(p=>p.team==='user').sort((a,b)=>b.g-a.g||b.a-a.a);return `<section class="panel"><div class="panel-heading"><h2>Temporada ${state.season}</h2><span class="small muted">Inclui jogadores vendidos</span></div>${stats.length?`<div class="table-wrap"><table><thead><tr><th>Jogador</th><th>Pos.</th><th class="numeric">J</th><th class="numeric">Gols</th><th class="numeric">Assist.</th><th class="numeric">Nota</th></tr></thead><tbody>${stats.map(p=>`<tr><td>${esc(D.byId[p.id].name)}</td><td class="muted">${D.byId[p.id].pos}</td><td class="numeric">${p.apps}</td><td class="numeric gold-text"><b>${p.g}</b></td><td class="numeric">${p.a}</td><td class="numeric">${(p.ratingSum/p.apps).toFixed(1)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">'+icon('chart')+'<h3>A história ainda vai começar</h3><p>As estatísticas aparecem depois da sua primeira partida.</p></div>'}</section>`;}
function shop(){return `${heading('Recrutamento','Um pacote. Novas possibilidades.','Cartas repetidas viram moedas automaticamente. Seu elenco nunca perde espaço.')}${state.pendingPack?`<div class="shop-banner"><div><h2>Você tem cartas para revelar</h2><p>Seu pacote já foi recebido. Continue de onde parou.</p></div><button class="btn" data-action="resume-pack">Revelar</button></div>`:''}${state.phase==='finished'?'<div class="notice" style="margin-bottom:22px">Sua carreira terminou. O elenco e a coleção continuam disponíveis para consulta.</div>':''}<div class="shop-grid">${D.packs.filter(p=>p.id!=='welcome').map(p=>{const locked=state.season<p.unlock;return `<article class="shop-item ${p.tier}"><div class="shop-art">${packet(p)}</div><div class="shop-content"><div class="space"><h2>${p.name}</h2><span class="chip ${p.tier==='elite'?'gold':'muted'}">${p.min}+</span></div><p>${p.desc}</p><button class="btn ${p.tier==='elite'?'secondary':''}" data-action="buy-pack" data-id="${p.id}" ${locked||state.coins<p.price||state.phase==='finished'||state.pendingPack?'disabled':''}>${locked?icon('lock')+' Temporada '+p.unlock:money(p.price)}</button><small>${locked?'Desbloqueie avançando na carreira':state.coins<p.price?'Faltam '+n(p.price-state.coins)+' moedas':p.subtitle}</small><button class="text-button" data-action="pack-info" data-id="${p.id}" style="width:100%;font-size:.73rem">Ver conteúdo e chances</button></div></article>`;}).join('')}</div>`;}
function league(){return `${heading('Liga brasileira','A disputa pela taça.',`20 clubes · 19 rodadas · Temporada ${state.season}`)}<div class="subtabs">${[['table','Classificação'],['fixtures','Rodadas'],['scorers','Artilharia'],['news','Notícias']].map(([id,label])=>`<button class="${leagueTab===id?'active':''}" data-action="league-tab" data-tab="${id}">${label}</button>`).join('')}</div>${leagueTab==='table'?leagueTable():leagueTab==='fixtures'?fixtures():leagueTab==='scorers'?scorers():`<section class="panel">${news()}</section>`}`;}
function leagueTable(){return `<section class="panel"><div class="panel-heading"><h2>${state.round===19?'Classificação final':'Tabela da liga'}</h2><span class="chip muted">${state.round}/19 rodadas</span></div><div class="table-wrap"><table class="table-full"><thead><tr><th>#</th><th>Clube</th><th class="numeric">PTS</th><th class="numeric">J</th><th class="numeric">V</th><th class="numeric">E</th><th class="numeric">D</th><th class="numeric">GP</th><th class="numeric">GC</th><th class="numeric">SG</th><th class="table-form">Últimos 5</th></tr></thead><tbody>${E.ranked(state).map((r,i)=>`<tr class="${r.id==='user'?'user-row':''}"><td class="table-rank ${i===0?'gold-text':''}">${i+1}</td><td><span class="table-team">${badge(E.team(state,r.id),'tiny')}<strong>${esc(E.team(state,r.id).name)}</strong></span></td><td class="numeric"><strong>${r.pts}</strong></td><td class="numeric">${r.played}</td><td class="numeric">${r.w}</td><td class="numeric">${r.d}</td><td class="numeric">${r.l}</td><td class="numeric">${r.gf}</td><td class="numeric">${r.ga}</td><td class="numeric">${r.gf-r.ga>0?'+':''}${r.gf-r.ga}</td><td class="table-form">${formDots(r)}</td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:17px">Desempate: pontos, vitórias, saldo e gols marcados. Empate total: ordem fixa dos clubes. A liga mantém os mesmos participantes nas cinco temporadas.</p></section>`;}
function fixtures(){leagueRound=Math.max(0,Math.min(18,leagueRound));let fixtures=state.results[leagueRound]||state.fixtures[leagueRound];return `<section class="panel"><div class="round-selector"><h2>Calendário</h2><select id="round-select" aria-label="Escolher rodada">${Array.from({length:19},(_,i)=>`<option value="${i}" ${leagueRound===i?'selected':''}>Rodada ${i+1}${i<state.round?' · finalizada':''}</option>`).join('')}</select></div>${fixtures.map(m=>`<div class="match-row ${m.home==='user'||m.away==='user'?'mine':''}"><div class="home"><span>${esc(E.team(state,m.home).name)}</span>${badge(E.team(state,m.home),'tiny')}</div><div class="match-score">${m.hg!==undefined?m.hg+' : '+m.ag:'×'}${E.isDerby(state,m)?'<small class="derby-mini">CLÁSSICO</small>':''}</div><div class="away">${badge(E.team(state,m.away),'tiny')}<span>${esc(E.team(state,m.away).name)}</span></div></div>`).join('')}</section>`;}
function scorers(){return `<div class="lower-grid" style="margin-top:0">${[['g','Artilheiros'],['a','Garçons da liga']].map(([key,title])=>`<section class="panel"><div class="panel-heading"><h2>${title}</h2>${icon(key==='g'?'target':'star')}</div>${E.leaders(state,key).slice(0,15).map((p,i)=>`<div class="leader-row"><span class="rank">${i+1}</span>${mini(D.byId[p.id])}<div class="player-label"><strong class="small">${esc(D.byId[p.id].name)}</strong><small>${esc(E.team(state,p.team).name)}</small></div><strong class="number">${p[key]}</strong></div>`).join('')||'<div class="empty">A bola ainda não rolou.</div>'}</section>`).join('')}</div>`;}
function career(){if(careerTab!=='current')return `${heading('Seu legado',careerTab==='album'?'O álbum da resenha.':'Hall da Fama pessoal.','Suas memórias continuam entre carreiras.')}${B.tabs(careerTab)}${bookContent()}`;let c=E.career(state);return `${heading('Seu legado','Cinco temporadas. Uma história.',state.phase==='finished'?'Sua carreira está completa. Agora é hora de compartilhar.':'Cada temporada deixa uma marca no clube.')}${B.tabs(careerTab)}${B.recordBanner(clubBook,state)}${window.OuroStory.cabinet(c)}${B.rivalry(state,badge)}${G.summary(state)}${G.reward(legacyProfile,card)}${state.phase==='finished'?`<div class="final-layout"><div><canvas id="career-canvas" class="final-image" width="1080" height="1350" aria-label="Retrospectiva da carreira de ${esc(state.club.name)}"></canvas><div class="actions" style="margin-top:16px"><button class="btn" data-action="download-final">${icon('download')} Baixar imagem</button><button class="btn secondary" data-action="share-final">${icon('share')} Compartilhar</button></div></div><div class="stack"><section class="panel"><span class="eyebrow">Avaliação final</span><h2 style="font-size:1.8rem;margin:10px 0">${E.coachLabel(c.score)}</h2><p>Seu trabalho recebeu ${c.score}/100. ${c.titles?'Você levou o clube ao topo '+c.titles+' vez'+(c.titles>1?'es':'')+'.':'Seu melhor resultado foi o '+c.best+'º lugar.'}</p><div class="rule"></div>${statBoxes([[c.titles,'Títulos','gold-text'],[c.goals,'Gols'],[c.wins,'Vitórias'],[c.overall,'Força final','lime-text']])}<button class="btn ghost wide" data-action="new-career">Começar outra história</button></section><section class="panel"><h2>Os capítulos do clube</h2>${historyCards()}</section></div></div>`:`<section class="career-hero"><div class="space"><div><div class="eyebrow">Temporada ${state.season} de 5</div><h2>${state.history.length?E.coachLabel(c.score):'Toda lenda tem um começo.'}</h2><p>${state.history.length?`Melhor colocação: ${c.best}º · ${c.titles} título${c.titles!==1?'s':''} conquistado${c.titles!==1?'s':''}`:'O primeiro capítulo está sendo escrito. No final, sua retrospectiva vira uma imagem para compartilhar.'}</p></div>${icon('trophy')}</div><div class="season-rail" style="margin-top:24px">${[1,2,3,4,5].map(i=>`<span class="${i<=state.history.length?'done':''}" style="height:6px"></span>`).join('')}</div></section>${statBoxes([[state.history.length,'Temporadas concluídas'],[c.titles,'Títulos','gold-text'],[Object.values(state.careerStats).reduce((a,p)=>a+p.g,0),'Gols na carreira'],[state.packsOpened,'Pacotes abertos']])}<section class="panel"><h2>Os capítulos do clube</h2>${state.history.length?historyCards():'<div class="empty">'+icon('calendar')+'<h3>Sua primeira temporada está em andamento</h3><p>Resultados, prêmios e avaliações ficarão guardados aqui.</p></div>'}</section>`}`;}
function historyCards(){return state.history.map(h=>`<article class="history-card"><span class="season-number">0${h.season}</span><div><h3>${h.position===1?'Campeões!':'Temporada '+h.season}</h3><p>Campeão: ${esc(h.champion.name)}<br>${h.scorer?'Artilheiro: '+esc(h.scorer.name)+' ('+h.scorer.g+' gols)':''}</p>${h.scorer?.team==='user'||h.ballWinner?.team==='user'?`<div class="history-awards">${h.scorer?.team==='user'?window.OuroStory.symbol('boot'):''}${h.ballWinner?.team==='user'?window.OuroStory.symbol('ball'):''}</div>`:''}<button class="text-button" data-action="history-summary" data-season="${h.season}">Ver retrospectiva</button></div><div class="history-place"><strong class="${h.position===1?'gold-text':''}">${h.position}º</strong><small>${h.score}/100</small></div></article>`).join('');}
function openModal(content,type='',className=''){modalType=type;modal.className=className;modal.innerHTML=content;if(!modal.open)modal.showModal();modal.scrollTop=0;if(type!=='match')requestAnimationFrame(()=>modal.querySelector('button:not(:disabled),select,input')?.focus({preventScroll:true}));}
function closeModal(){clearInterval(matchTimer);matchTimer=null;stopPackAnimation();modal.close();modalType='';}
function dialog(title,body,actions='',description=''){return `<div class="dialog-body"><div class="dialog-top"><div><h2 id="dialog-title">${title}</h2>${description?`<p>${description}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}</div>`;}
function specialDetails(p){if(p.special==='legacy')return '<section class="special-details"><h3>Lenda do clube · carta permanente</h3><p>Criada ao completar três objetivos. Acompanha seus próximos clubes, tem 88 OVR e não sai por venda ou evento.</p></section>';if(p.special!=='totw')return '';const base=D.byId[p.baseId];return `<section class="special-details"><h3>${esc(p.editionLabel)} · ${esc(p.edition)}</h3><p>${esc(p.reason)}</p><div class="boost-list">${[['ovr','OVR'],['vel','VEL'],['fin','FIN'],['pas','PAS'],['def','DEF'],['fis','FÍS'],['gol','GOL']].filter(([key])=>p[key]>base[key]).map(([key,label])=>`<span>${label} ${base[key]} → ${p[key]} (+${p[key]-base[key]})</span>`).join('')}</div><a class="small" href="${esc(p.source.url)}" target="_blank" rel="noopener noreferrer">Ver a atuação que inspirou a carta</a></section>`;}
function showPlayer(id){const p=D.byId[id],stats=state.stats['user:'+id],reason=E.saleReason(state,id);openModal(dialog(esc(p.name),`<div class="player-detail">${card(p)}<div class="player-meta"><span class="chip gold">${{bronze:'Bronze',silver:'Prata',gold:'Ouro',elite:'Elite',totw:'Time da Semana',legacy:'Lenda do clube'}[E.tier(p)]}</span><p>${D.nations[p.nation]||p.nation} · ${p.pos}<br>${state.lineup.includes(id)?'No time titular':state.bench.includes(id)?'No banco':'Disponível no clube'}</p><div class="stats-list"><div><span>Jogos</span><strong>${stats?.apps||0}</strong></div><div><span>Gols</span><strong>${stats?.g||0}</strong></div><div><span>Assistências</span><strong>${stats?.a||0}</strong></div><div><span>Nota média</span><strong>${stats?(stats.ratingSum/stats.apps).toFixed(1):'—'}</strong></div></div><div class="gold-text"><strong>${money(E.value(p))}</strong><small class="muted" style="display:block">Valor de venda</small></div></div></div>${specialDetails(p)}${B.nickDetails(state,id)}${reason?`<p class="small muted" style="margin-top:18px">${reason}</p>`:''}`,`<button class="btn secondary" data-action="assign-player" data-id="${id}" ${state.phase==='finished'?'disabled':''}>${icon('users')} Escalar</button><button class="btn ghost" data-action="confirm-sale" data-id="${id}" ${reason?'disabled':''}>Vender jogador</button>`),'player');}
function picker(slot,benchId){if(state.phase==='finished'){showPlayer(benchId||state.lineup[slot]);return;}const pos=benchId?null:D.formations[state.formation][slot][0],current=benchId||state.lineup[slot];let ids=state.squad.filter(id=>id!==current&&(!benchId||!state.lineup.includes(id))).sort((a,b)=>pos?D.byId[b].ovr*E.fit(D.byId[b],pos)-D.byId[a].ovr*E.fit(D.byId[a],pos):D.byId[b].ovr-D.byId[a].ovr);
 openModal(dialog(benchId?'Trocar reserva':'Escolher '+pos,`<p class="small muted" style="margin-bottom:13px">No lugar de ${esc(D.byId[current].name)}. ${benchId?'O banco participa das substituições automáticas.':'A força efetiva considera a adequação à posição.'}</p><div class="picker">${ids.map(id=>{const p=D.byId[id],f=pos?E.fit(p,pos):1;return `<button class="picker-row" data-action="${benchId?'set-bench':'set-slot'}" data-id="${id}" ${benchId?`data-out="${benchId}"`:`data-slot="${slot}"`}><span class="picker-ovr">${p.ovr}</span><span class="picker-name"><strong>${esc(p.name)}</strong><small>${p.pos} · ${state.lineup.includes(id)?'Titular':state.bench.includes(id)?'Reserva':'No clube'}</small></span><span class="picker-fit ${f<.9?'gold-text':''}">${pos?Math.round(p.ovr*f)+' OVR':p.nation}<small>${pos?Math.round(f*100)+'% de adequação':''}</small></span>${icon('swap')}</button>`;}).join('')}</div>`),'picker');}
function assignPlayer(id){const p=D.byId[id];openModal(dialog('Onde escalar '+esc(p.name)+'?',`<div class="picker">${D.formations[state.formation].map(([pos],i)=>`<button class="picker-row" data-action="set-slot" data-slot="${i}" data-id="${id}"><span class="picker-ovr">${pos}</span><span class="picker-name"><strong>${esc(D.byId[state.lineup[i]].name)}</strong><small>Atual: ${D.byId[state.lineup[i]].ovr} OVR</small></span><span class="picker-fit">${Math.round(p.ovr*E.fit(p,pos))} OVR<small>Com ${esc(p.name)}</small></span></button>`).join('')}</div>`),'assign');}
function weeklyRoster(){return `<section class="weekly-preview"><div class="weekly-heading"><span class="chip gold">${esc(D.weekly.label)}</span><h3>${esc(D.weekly.period)}</h3><p>${esc(D.weekly.note)}</p></div><div class="weekly-roster">${D.weekly.cards.map(p=>`<article>${mini(p)}<div><b>${esc(p.name)}</b><span>${p.pos} · ${D.byId[p.baseId].ovr} → ${p.ovr} OVR</span><p>${esc(p.reason)}</p><a href="${esc(p.source.url)}" target="_blank" rel="noopener noreferrer">Ver atuação</a></div></article>`).join('')}</div></section>`;}
function packInfo(id,buy=false){
 const p=D.packs.find(x=>x.id===id),pool=E.packPool(state,p).filter(x=>x.ovr>=p.min),weight=x=>Math.pow(.65,x.ovr-p.min),sum=pool.reduce((a,x)=>a+weight(x),0),elite=sum?pool.filter(x=>x.ovr>=88).reduce((a,x)=>a+weight(x),0)/sum*100:0;
 let chances=p.mode==='choice'?'<h3>Três opções, uma contratação</h3><p class="small muted">As três cartas são diferentes, todas entre 80 e 85. Notas menores são mais frequentes. Só a carta confirmada entra no elenco; as outras duas não geram moedas. Se a escolhida já for sua, apenas ela vira moedas.</p>':`<h3>Chances das cartas adicionais</h3><p class="small muted">Bronze (68–74): ${p.weights[0]}% · Prata (75–79): ${p.weights[1]}%<br>Ouro (80–87): ${p.weights[2]}% · Elite (88+): ${p.weights[3]}%</p><p class="small muted">${p.id==='totw'?'A primeira carta é uma das 11 desta edição, com chances iguais entre as disponíveis. As outras é são comum.':`Na carta garantida, a chance de 88+ é ${elite.toFixed(1)}%. Notas maiores são mais raras.`} Repetidas viram moedas. Versões comuns e da semana são cartas diferentes.</p>`;
 openModal(dialog(p.name,`<div class="pack-info-intro">${packet(p)}<div><h3>${p.desc}</h3><p>${p.subtitle}</p><strong class="gold-text">${money(p.price)}</strong></div></div><div class="rule"></div><div class="pack-chances">${chances}<p class="small muted">Somente moedas do jogo, sem dinheiro real.</p></div>${p.id==='totw'?weeklyRoster():''}`,buy?`<button class="btn secondary" data-action="close">Voltar</button><button class="btn" data-action="purchase" data-id="${id}">Abrir por ${money(p.price)}</button>`:''),'pack-info',p.id==='totw'?'weekly-dialog':'');
}
let packStage='sealed',packTimers=[],choiceCandidate=null;
function stopPackAnimation(){packTimers.forEach(clearTimeout);packTimers=[];}
function animatePackCard(){
 if(!state.pendingPack||packStage==='reveal')return;
 if(state.pendingPack.revealed>=state.pendingPack.cards.length){showPack('results');return;}
 E.reveal(state);save();stopPackAnimation();packStage='reveal';
 const pending=state.pendingPack,p=D.packs.find(x=>x.id===pending.packId),player=D.byId[pending.cards[pending.revealed-1].id],premium=!['base','silver'].includes(p.id)&&player.ovr>=80;
 const stats=[['vel','VEL'],['fin','FIN'],['pas','PAS'],['def','DEF'],['fis','FÍS'],['gol','GOL']];
 openModal(`<div class="pack-stage"><div class="eyebrow">${esc(p.name)} · Carta ${pending.revealed} de ${pending.cards.length}</div><h2 id="dialog-title">Quem vem para o XI?</h2><div class="walkout ${premium?'premium':''} ${p.tier}" data-step="stats"><span class="walkout-mark" aria-hidden="true">XI</span><div class="walkout-stats">${stats.map(([key,label],i)=>`<div style="--i:${i}"><b>${player[key]}</b><span>${label}</span></div>`).join('')}</div><div class="walkout-position" aria-live="polite"></div><div class="walkout-slogan" aria-live="polite"></div><div class="walkout-rail" aria-hidden="true"><i></i><i></i><i></i></div></div><div class="dialog-actions"><button class="btn ghost" data-action="skip-reveal">Pular animação</button></div></div>`,'pack','pack-dialog');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,scale=reduced?.18:prefs.quick?.45:1;
 const cue=(delay,fn)=>packTimers.push(setTimeout(()=>{if(state.pendingPack===pending&&modalType==='pack'&&packStage==='reveal')fn();},delay*scale));
 sound('click');
 cue(premium?1100:800,()=>{const scene=modal.querySelector('.walkout');scene.dataset.step='position';scene.querySelector('.walkout-position').innerHTML=`<b>${player.pos}</b><span>${esc(D.nations[player.nation]||player.nation)}</span>`;sound('click');});
 cue(premium?2200:1500,()=>{const scene=modal.querySelector('.walkout');scene.dataset.step='slogan';scene.querySelector('.walkout-slogan').textContent=E.revealLabel(p,player);sound('pack');});
 cue(premium?3500:2500,()=>{showPack('card');sound('pack');});
}
function showPack(stage){
 if(!state.pendingPack)return;stopPackAnimation();
 const pending=state.pendingPack,p=D.packs.find(x=>x.id===pending.packId),choice=pending.mode==='choice';
 packStage=stage||(pending.selected||pending.revealed===pending.cards.length?'results':pending.revealed?'card':'sealed');let content='';
 if(packStage==='sealed'){
   choiceCandidate=null;
   content=`<div class="eyebrow gold-text">${p.id==='welcome'?'Seu clube começa aqui':choice?'Você decide quem fica':'Nova contratação'}</div><h2 id="dialog-title">${p.name}</h2><p>${p.desc}</p><button class="packet-button" data-action="reveal-card" aria-label="Toque para abrir o pacote">${packet(p)}</button><div class="dialog-actions"><button class="btn ghost" data-action="reveal-all">${choice?'Ver as três opções':'Revelar todas'}</button></div>`;
 }else if(packStage==='card'){
   const c=pending.cards[Math.max(0,pending.revealed-1)],player=D.byId[c.id];
   content=`<div class="eyebrow gold-text">${esc(E.revealLabel(p,player))}</div><h2 id="dialog-title">${esc(player.name)}</h2><p>${D.nations[player.nation]||player.nation} · ${player.pos}${player.special?' · '+esc(player.editionLabel):''}</p><div class="reveal-card ${player.special?'special-reveal':''}">${card(player)}</div><span class="chip ${c.duplicate?'gold':''}">${choice?c.duplicate?'Já está no elenco · moedas só se escolhida':'Uma das três opções':c.duplicate?'Repetida · + '+n(c.refund)+' moedas':'Nova carta no seu elenco'}</span><div class="pack-progress">${pending.cards.map((_,i)=>`<i class="${i<pending.revealed?'on':''}"></i>`).join('')}</div><div class="dialog-actions"><button class="btn ghost" data-action="reveal-all">Ver todas</button><button class="btn" data-action="${pending.revealed>=pending.cards.length?'pack-results':'reveal-card'}">${pending.revealed>=pending.cards.length?choice?'Escolher meu jogador':'Ver reforços':'Próxima carta'}</button></div>`;
 }else{
   const deciding=choice&&!pending.selected,received=choice?pending.cards.filter(c=>c.id===pending.selected):pending.cards,selected=choiceCandidate&&pending.cards.find(c=>c.id===choiceCandidate);
   content=`<div class="eyebrow gold-text">Pacote ${p.name}</div><h2 id="dialog-title">${deciding?'Três nomes. Uma vaga no XI.':choice?'Contratação confirmada!':'Novas possibilidades para o seu XI.'}</h2><p>${deciding?'Compare os atributos e confirme uma carta.':received.filter(c=>!c.duplicate).length+' carta(s) nova(s)'+(received.some(c=>c.duplicate)?' · '+n(received.reduce((a,c)=>a+c.refund,0))+' moedas de repetidas':'')}</p><div class="pack-results ${choice?'choice-results':''}">${(deciding?pending.cards:received).map(c=>`<div class="pack-result ${choiceCandidate===c.id?'selected':''}">${card(D.byId[c.id])}<p class="${c.duplicate?'duplicate':''}">${c.duplicate?(deciding?'Se escolhida: +':'Repetida: +')+n(c.refund)+' moedas':deciding?'Disponível para contratação':'Adicionado ao elenco'}</p>${deciding?`<button class="btn secondary wide" data-action="choose-pack-option" data-id="${c.id}" aria-pressed="${choiceCandidate===c.id}">${choiceCandidate===c.id?icon('check')+' Selecionado':'Escolher '+esc(D.byId[c.id].name)}</button>`:''}</div>`).join('')}</div><div class="dialog-actions">${deciding?`<button class="btn" data-action="confirm-pack-choice" data-id="${selected?.id||''}" ${selected?'':'disabled'}>${selected?'Confirmar '+esc(D.byId[selected.id].name):'Selecione um jogador'}</button>`:`<button class="btn secondary" data-action="finish-pack" data-next="packs">Continuar</button><button class="btn" data-action="finish-pack" data-next="squad">${icon('users')} Ajustar elenco</button>`}</div>`;
 }
 openModal(`<div class="pack-stage">${content}</div>`,'pack','pack-dialog');
}
function prematch(){if(state.pendingPack){showPack();return;}if(state.phase!=='active'){seasonSummary();return;}const p=E.preview(state),own=E.metrics(E.team(state,'user')),opp=E.metrics(p.fixture.home==='user'?p.away:p.home);openModal(dialog(E.isDerby(state,p.fixture)?'Clássico: hoje vale a resenha!':'Tudo pronto para entrar em campo?',`${B.derbyRibbon(state,p.fixture)}<div class="fixture-teams"><div class="fixture-team">${badge(p.home,'large')}<strong>${esc(p.home.name)}</strong></div><div class="vs">VS</div><div class="fixture-team">${badge(p.away,'large')}<strong>${esc(p.away.name)}</strong></div></div><div class="metrics"><div class="metric"><strong class="lime-text">${own.overall}</strong><small>Seu time</small></div><div class="metric"><strong>${p.win}%</strong><small>Chance de vitória</small></div><div class="metric"><strong>${opp.overall}</strong><small>Adversário</small></div></div><p class="dialog-help" style="margin-top:18px">${state.formation} · ${D.tactics[state.tactic].name}<br>Capitão: ${esc(D.byId[state.captain].name)}<br>Empate: ${p.draw}% · Derrota: ${p.loss}%</p>${own.fit<95?'<div class="notice" style="margin-top:14px">Há jogadores adaptados. Ajustar as posições pode melhorar seu rendimento.</div>':''}`,`<button class="btn secondary" data-action="edit-before-match">Ajustar time</button><button class="btn" data-action="simulate">${icon('play')} Simular partida</button>`,'Seu time titular e seu banco serão usados nesta partida.'),'prematch');}
function playMatch(){if(modalType==='match'&&matchTimer)return;const m=E.advanceRound(state);state.unseenMatch=true;save();render();matchMinute=prefs.quick?90:0;showMatch(m,matchMinute);if(!prefs.quick){clearInterval(matchTimer);matchTimer=setInterval(()=>{matchMinute=Math.min(90,matchMinute+9);showMatch(m,matchMinute);if(matchMinute>=90){clearInterval(matchTimer);matchTimer=null;const win=(m.home==='user'?m.hg>m.ag:m.ag>m.hg);if(win)sound('win');}},150);}}
function matchReason(m){const t=E.metrics(E.team(state,'user')),op=E.metrics(E.team(state,m.home==='user'?m.away:m.home)),home=m.home==='user',xg=m.xg[home?0:1],against=m.xg[home?1:0];let reason=t.fit<92?'As adaptações de posição reduziram a força do seu time.':t.mid>op.mid+5?'Seu meio-campo teve vantagem técnica na criação.':t.attack<op.defense-5?'Seu ataque encontrou uma defesa tecnicamente superior.':state.tactic==='press'?'A pressão alta aumentou as oportunidades para os dois lados.':state.tactic==='counter'?'O time procurou acelerar quando encontrou espaços.':'Os setores chegaram equilibrados para a partida.';return `${reason} Chances estimadas: ${xg.toFixed(1)} a ${against.toFixed(1)}. A eficiência nas finalizações decidiu o placar.`;}
function showMatch(m,minute=90){const final=minute===90,events=m.events.filter(e=>e.minute<=minute),hg=final?m.hg:events.filter(e=>e.team===m.home).length,ag=final?m.ag:events.filter(e=>e.team===m.away).length;const home=E.team(state,m.home),away=E.team(state,m.away);openModal(`<div class="match-head">${B.derbyRibbon(state,m)}<div class="match-status ${final?'':'simulating'}" id="dialog-title">${final?'Fim de jogo':minute+"' · Bola rolando"} · Rodada ${m.round}</div><div class="fixture-teams"><div class="fixture-team">${badge(home,'large')}<strong>${esc(home.name)}</strong></div><div class="big-score">${hg} : ${ag}</div><div class="fixture-team">${badge(away,'large')}<strong>${esc(away.name)}</strong></div></div></div><div class="match-body"><div class="match-events">${events.map(e=>`<div class="goal-event ${e.team==='user'?'user-goal':''}"><span class="minute">${e.minute}'</span><span>${icon('target')}</span><span><strong>${esc(D.byId[e.scorer].name)}</strong><small>${esc(E.team(state,e.team).short)} · ${e.assist?'Passe de '+esc(D.byId[e.assist].name):'Jogada individual'}</small></span></div>`).join('')||`<p class="empty" style="padding:15px">${final?'As redes não balançaram desta vez.':'As equipes buscam espaço…'}</p>`}</div>${final?`<div class="match-stats"><div class="match-stat"><strong>${m.possession[0]}%</strong><span>Posse de bola</span><strong>${m.possession[1]}%</strong></div><div class="match-stat"><strong>${m.shots[0]}</strong><span>Finalizações</span><strong>${m.shots[1]}</strong></div><div class="match-stat"><strong>${m.xg[0]}</strong><span>Gols esperados</span><strong>${m.xg[1]}</strong></div></div><p class="match-explanation">${matchReason(m)}</p><div class="space" style="margin:10px 0 17px"><span class="small">${icon('star')} Melhor em campo: <strong>${esc(D.byId[m.motm.id].name)}</strong></span><span class="chip gold">${m.motm.rating.toFixed(1)}</span></div><div class="reward-box"><span>Prêmio da partida</span><strong>+ ${money(m.reward)}</strong></div><div class="dialog-actions"><button class="btn secondary" data-action="match-details">Ver notas</button><button class="btn" data-action="match-continue">${state.phase==='active'?'Continuar':'Ver fim da temporada'}</button></div>`:`<div class="dialog-actions"><button class="btn secondary" data-action="skip-match">Ver resultado agora</button></div>`}</div>`,'match','match-dialog');}
function matchDetails(){let m=state.lastMatch;openModal(dialog('Notas da partida',`<div class="table-wrap"><table><thead><tr><th>Jogador</th><th class="numeric">Min.</th><th class="numeric">G</th><th class="numeric">A</th><th class="numeric">Nota</th></tr></thead><tbody>${m.ratings.filter(p=>p.team==='user').sort((a,b)=>b.rating-a.rating).map(p=>`<tr><td>${esc(D.byId[p.id].name)} ${p.from?'<small class="muted">(entrou)</small>':''}</td><td class="numeric">${p.to-p.from}</td><td class="numeric">${p.g}</td><td class="numeric">${p.a}</td><td class="numeric gold-text"><b>${p.rating.toFixed(1)}</b></td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:15px">O banco entra automaticamente conforme posição, qualidade e desgaste dos titulares durante a partida.</p>`,`<button class="btn secondary" data-action="last-match">Voltar ao resultado</button><button class="btn" data-action="match-continue">Continuar</button>`),'match-details');}
let storySeason=null,storyStep=0,careerSimulationRunning=false;
function seasonSummary(season,step){
 const h=state.history.find(h=>h.season===(season||state.season));if(!h)return;
 E.ensureSeason(state,h);storySeason=h.season;storyStep=step===undefined?0:Math.max(0,Math.min(4,step));
 if(h.season===state.season){h.reviewStep=storyStep;save();}
 openModal(window.OuroStory.render(state,h,storyStep),'season','story-dialog');
}
async function simulateCareerTurn(){
 if(careerSimulationRunning)return;
 if(state.pendingPack){showPack();toast('Revele o pacote antes de simular.');return;}
 if(state.phase==='finished'){seasonSummary();return;}
 state.autoCareer=true;save();
 if(state.phase==='seasonEnd'){seasonSummary();return;}
 careerSimulationRunning=true;
 const running=state;
 openModal('<div class="dialog-body story-heading"><span class="eyebrow">Simulação da carreira</span><h2 id="dialog-title">A bola está rolando…</h2><p>Usando seus titulares, banco, formação e tática. A próxima pausa será no encerramento da temporada.</p></div>','simulating-career','story-dialog');
 try{
   while(state===running&&state.phase==='active'){
     E.advanceRound(state);
     if(state.round%3===0)await new Promise(resolve=>setTimeout(resolve,0));
   }
   if(state!==running)return;
   state.unseenMatch=false;save();render();seasonSummary();
 }catch(error){state.autoCareer=false;save();closeModal();render();toast(error.message);}
 finally{careerSimulationRunning=false;}
}
function settings(){openModal(dialog('Seu jogo, do seu jeito',`<div class="setting-row"><div><h3>Sons do jogo</h3><p>Abertura de pacotes e vitórias.</p></div><input type="checkbox" id="sound-toggle" ${prefs.sound?'checked':''} aria-label="Ativar sons"></div><div class="setting-row"><div><h3>Resultados imediatos</h3><p>Pular a apresentação rápida da partida.</p></div><input type="checkbox" id="quick-toggle" ${prefs.quick?'checked':''} aria-label="Resultados imediatos"></div><div class="rule"></div><h3>Seu progresso</h3><p class="dialog-help" style="margin-top:8px">${savingOK?'O jogo é salvo automaticamente neste navegador.':'O salvamento automático está indisponível.'} Exporte um backup para guardar ou levar sua carreira para outro dispositivo.</p><div class="actions" style="margin-top:15px"><button class="btn secondary small" data-action="export">${icon('download')} Exportar progresso</button><button class="btn ghost small" data-action="import">Importar progresso</button></div><div class="rule"></div><div class="space"><button class="text-button" data-action="help">Como jogar</button><button class="btn ghost small" data-action="new-career">Nova carreira</button></div>`),'settings');}
function help(){openModal(dialog('Como construir seu XI de craques',`<div class="help-list"><div><h3>1. Abra e escale</h3><p>O pacote inicial já inclui uma carta 80+. Em Elenco, toque em um titular para trocar. A opção Melhor escalação considera a posição de cada jogador.</p></div><div><h3>2. Prepare o time</h3><p>Escolha formação, capitão e tática. Uma adaptação reduz os atributos efetivos. O banco faz até três substituições automáticas; bons reservas mantêm o time competitivo.</p></div><div><h3>3. Jogue e melhore</h3><p>Cada partida paga 350 moedas. Vitória soma 450, empate soma 180, e cada gol vale 60 (até cinco). Objetivos e vendas também rendem moedas.</p></div><div><h3>4. Abra novos pacotes</h3><p>Ouro garante 80+, Elite garante 85+ a partir da segunda temporada e Galáctico garante 88+ na terceira. Cartas repetidas viram moedas. Venda reservas mantendo pelo menos 18 jogadores e dois goleiros.</p></div><div><h3>5. Construa uma carreira</h3><p>São 19 rodadas por temporada e cinco temporadas. Os rivais evoluem e um evento diferente nas quatro transições pode tirar jogadores ou moedas. Toda temporada tem balanço, Chuteira de Ouro, Bola de Ouro e jornal. Simular tudo usa sua escalação e pausa nesses momentos para você decidir. No fim, baixe e compartilhe uma imagem do seu legado.</p></div><div><h3>Sobre esta liga</h3><p>Clubes brasileiros e jogadores reais em elencos de fantasia. Atributos são próprios do jogo. O resultado considera setores, posições, tática, mando, banco e variação nas finalizações. Força maior aumenta as chances; não garante vitória.</p></div></div>`),'help');}
function confirmSale(id){const p=D.byId[id];openModal(dialog('Vender '+esc(p.name)+'?',`<p class="dialog-help">O jogador sai do clube e você recebe <strong class="gold-text">${n(E.value(p))} moedas</strong>. Os números dele nesta carreira ficam no histórico.</p>`,`<button class="btn secondary" data-action="player" data-id="${id}">Manter jogador</button><button class="btn" data-action="sell" data-id="${id}">Confirmar venda</button>`),'sale');}
function exportSave(){if(state)save();else try{syncBook();}catch{}download(new Blob([JSON.stringify({game:'xi-e-craque',version:1,state,legacyProfile,clubBook},null,2)],{type:'application/json'}),'xi-e-craque-progresso.json');toast('Backup da carreira, das recompensas e das memórias exportado.');}
function importSave(){
 const input=document.createElement('input');input.type='file';input.accept='.json,application/json';
 input.addEventListener('change',async()=>{try{
   const f=input.files[0];if(!f)return;if(f.size>8e6)throw Error('O arquivo de progresso é grande demais.');
   const imported=JSON.parse(await f.text());
   if(!['xi-e-craque','onze-de-ouro'].includes(imported.game)||(imported.state!==null&&!E.validate(imported.state))||(imported.state===null&&!imported.clubBook))throw Error('Este arquivo não é um progresso válido do XI, é Craque.');
   if(imported.legacyProfile&&!E.validLegacyProfile(imported.legacyProfile))throw Error('A recompensa deste backup não é válida.');
   if(imported.clubBook&&!E.validClubBook(imported.clubBook))throw Error('O álbum ou o Hall da Fama deste backup não é válido.');
   window.pendingImport=imported.state;window.pendingLegacyImport=imported.legacyProfile||null;window.pendingBookImport=imported.clubBook||null;
   const description=imported.state?`<strong>${esc(imported.state.club.name)}</strong><br>Temporada ${imported.state.season} · ${imported.state.round} rodadas jogadas.<br>${state?'Isso substituirá a carreira atual neste navegador.':'Seu clube está pronto para continuar.'}`:'Este backup contém suas memórias. A carreira atual, se houver, será mantida.';
   openModal(dialog('Carregar este progresso?',`<p class="dialog-help">${description}<br><br>As descobertas do álbum e as carreiras do Hall serão somadas às que já estão neste navegador.</p>`,`<button class="btn secondary" data-action="close">Cancelar</button><button class="btn" data-action="apply-import">Carregar progresso</button>`),'import');
 }catch(e){toast(e.message);}});input.click();
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function drawFinal(canvas){return window.OuroStory.drawFinal(canvas,state);}
async function finalBlob(){let canvas=$('#career-canvas')||document.createElement('canvas');drawFinal(canvas);return await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Não foi possível gerar a imagem.')),'image/png'));}
async function shareFinal(){const blob=await finalBlob(),file=new File([blob],'minha-carreira-xi-e-craque.png',{type:'image/png'});if(navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({title:'Meu XI, é Craque',text:state.club.name+' · cinco temporadas de história.',files:[file]});}catch(e){if(e.name!=='AbortError')throw e;}}else{download(blob,'minha-carreira-xi-e-craque.png');toast('Imagem baixada! Agora é só enviar na sua rede favorita.');}}
function recoverPending(){if(!state)return;if(state.phase!=='active')E.ensureSeason(state);if(state.pendingPack)showPack();else if(state.unseenMatch&&state.lastMatch)showMatch(state.lastMatch);else if(state.phase!=='active'&&!state.history.at(-1)?.reviewDone)seasonSummary(state.season,state.history.at(-1)?.reviewStep||0);else if(state.autoCareer&&state.phase==='active')simulateCareerTurn();}
// All game mutations go through the engine and are persisted before animations.
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;try{
 switch(action){
 case 'open-memories':try{syncBook();}catch(e){toast(e.message);}careerTab=b.dataset.tab||'album';view=state?'career':'memories';closeModal();render();window.scrollTo(0,0);break;
 case 'back-setup':view='club';render();break;
 case 'book-tab':careerTab=b.dataset.tab;view=state?'career':'memories';closeModal();render();break;
 case 'album-page':albumPage=Number(b.dataset.page);refreshAlbum();$('#album-results')?.scrollIntoView({block:'start',behavior:'auto'});break;
 case 'album-card':{const row=clubBook.album[id];if(!row)break;openModal(dialog(esc(row.player.name),B.albumDetail(clubBook,id,card,state)),'album-card');break;}
 case 'hall-career':{const row=clubBook.careers[id];if(!row)break;openModal(dialog('Uma carreira para guardar',B.hallDetail(row,badge)),'hall-career');break;}
 case 'choose-rival':openModal(dialog('Quem entra para a resenha?',B.rivalPicker(state),'<button class="btn" data-action="confirm-rival">Declarar rival</button>'),'rival');break;
 case 'confirm-rival':E.declareRival(state,$('#rival-select').value);save();closeModal();render();toast('Rival declarado! O próximo clássico já está no calendário.');break;
 case 'choose-goals':showGoalPicker();break;
 case 'toggle-goal':if(!state){if(draft.careerGoals.includes(id))draft.careerGoals=draft.careerGoals.filter(g=>g!==id);else if(draft.careerGoals.length<3&&E.careerGoalDefinitions.some(g=>g.id===id)&&!(id==='silver'&&legacyProfile.card))draft.careerGoals.push(id);refreshGoalSetup();showGoalPicker(true,id);}break;
 case 'clear-goals':draft.careerGoals=[];refreshGoalSetup();break;
 case 'clear-goals-modal':draft.careerGoals=[];refreshGoalSetup();showGoalPicker(true);break;
 case 'goals-done':closeModal();refreshGoalSetup();$('#career-goal-picker button')?.focus({preventScroll:true});break;
 case 'settle-final':{const amount=E.settleFinalCoins(state);save();render();sound('win');toast(n(amount)+' moedas destinadas à base. Selo J. Textor conquistado!');break;}
 case 'create-legend':syncLegacyProfile();if(!legacyProfile.unlocked||legacyProfile.card)throw Error('A criação da lenda não está disponível.');openModal(G.editor(),'legacy');previewLegacy();break;
 case 'nav':view=b.dataset.view;closeModal();render();window.scrollTo(0,0);break;
 case 'starter':draft.starter=id;renderSetup();break;
 case 'captain-draft':draft.captain=id;renderSetup();break;
 case 'reroll-captains':captainOptions=E.drawCaptains();draft.captain=captainOptions[0];renderSetup();break;
 case 'settings':settings();break;case 'help':help();break;
 case 'close':if(modalType==='match'&&state.unseenMatch){state.unseenMatch=false;save();}if(modalType==='season'){state.autoCareer=false;save();render();}closeModal();break;
 case 'squad-tab':squadTab=b.dataset.tab;render();break;
 case 'league-tab':leagueTab=b.dataset.tab;leagueRound=Math.min(state.round,18);render();break;
 case 'auto-lineup':E.optimize(state);E.updateObjectives(state);save();render();toast('Titulares e banco ajustados para a formação atual.');break;
 case 'tactic':state.tactic=id;save();render();break;
 case 'pick-slot':picker(Number(b.dataset.slot));break;
 case 'bench-picker':picker(null,id);break;
 case 'set-slot':E.swap(state,Number(b.dataset.slot),id);save();closeModal();render();toast('Escalação atualizada.');break;
 case 'set-bench':E.benchSwap(state,b.dataset.out,id);save();closeModal();render();toast('Banco atualizado.');break;
 case 'player':showPlayer(id);break;case 'assign-player':assignPlayer(id);break;
 case 'confirm-sale':confirmSale(id);break;
 case 'sell':{const amount=E.sell(state,id);save();closeModal();render();toast('Jogador vendido. + '+n(amount)+' moedas.');break;}
 case 'claim':{const amount=E.claim(state,id);save();render();sound('win');toast('Objetivo concluído! + '+n(amount)+' moedas.');break;}
 case 'buy-pack':packInfo(id,true);break;case 'pack-info':packInfo(id);break;
 case 'purchase':E.openPack(state,id);save();render();showPack('sealed');break;
 case 'resume-pack':showPack();break;
 case 'reveal-card':animatePackCard();break;
 case 'skip-reveal':showPack('card');break;
 case 'reveal-all':if(!state.pendingPack)break;state.pendingPack.revealed=state.pendingPack.cards.length;save();sound('pack');showPack('results');break;
 case 'pack-results':showPack('results');break;
 case 'choose-pack-option':choiceCandidate=id;showPack('results');break;
 case 'confirm-pack-choice':E.choosePackCard(state,id);save();choiceCandidate=null;render();showPack('results');sound('win');break;
 case 'finish-pack':E.finishPack(state);save();closeModal();view=b.dataset.next;if(view==='squad')squadTab='pitch';render();toast('Cartas recebidas. Escolha seus titulares antes de jogar.');break;
 case 'prematch':prematch();break;
 case 'edit-before-match':closeModal();view='squad';squadTab='pitch';render();break;
 case 'simulate':b.disabled=true;playMatch();break;
 case 'skip-match':clearInterval(matchTimer);matchTimer=null;showMatch(state.lastMatch);break;
 case 'last-match':showMatch(state.lastMatch);break;
 case 'match-details':matchDetails();break;
 case 'match-continue':state.unseenMatch=false;save();closeModal();if(state.phase!=='active')seasonSummary();else render();break;
 case 'simulate-all':await simulateCareerTurn();break;
 case 'season-summary':seasonSummary();break;
 case 'story-next':seasonSummary(storySeason,storyStep+1);break;
 case 'story-back':seasonSummary(storySeason,storyStep-1);break;
 case 'resolve-season-event':E.resolveSeasonEvent(state,b.dataset.choice);save();render();seasonSummary(storySeason,4);break;
 case 'stop-auto':state.autoCareer=false;save();seasonSummary(storySeason,storyStep);break;
 case 'history-summary':seasonSummary(Number(b.dataset.season));break;
 case 'next-season':E.nextSeason(state);save();closeModal();view='club';render();if(state.autoCareer)await simulateCareerTurn();else toast('Temporada '+state.season+' começou. Confira o elenco após o evento!');break;
 case 'finish-career':careerTab='current';state.history.at(-1).reviewDone=true;state.autoCareer=false;save();closeModal();view='career';render();window.scrollTo(0,0);break;
 case 'download-final':download(await finalBlob(),'minha-carreira-xi-e-craque.png');toast('Sua retrospectiva foi baixada.');break;
 case 'share-final':await shareFinal();break;
 case 'export':exportSave();break;case 'import':importSave();break;
 case 'apply-import':{
   try{syncBook();}catch{}
   if(window.pendingImport){state=window.pendingImport;E.ensureClubLore(state);E.updateNicknames(state);}
   if(window.pendingBookImport)clubBook=E.mergeClubBooks(clubBook,window.pendingBookImport);
   if(window.pendingLegacyImport)legacyProfile={version:1,unlocked:legacyProfile.unlocked||window.pendingLegacyImport.unlocked,card:legacyProfile.card||window.pendingLegacyImport.card};
   delete window.pendingImport;delete window.pendingLegacyImport;delete window.pendingBookImport;
   localStorage.setItem(BOOK_KEY,JSON.stringify(clubBook));localStorage.setItem(LEGACY_KEY,JSON.stringify(legacyProfile));window.bookCorrupted=false;
   if(state)save();closeModal();careerTab=state?'current':'album';view=state?'club':'memories';render();recoverPending();toast('Progresso carregado. Álbum e Hall preservados.');break;
 }
 case 'new-career':openModal(dialog('Começar uma nova carreira?',`<p class="dialog-help">Seu progresso atual será substituído. Exporte um backup se quiser guardar esta história. Sua lenda, o álbum permanente e o Hall da Fama continuam salvos. Carreiras interrompidas não entram no Hall.</p>`,`<button class="btn secondary" data-action="export">Exportar antes</button><button class="btn danger" data-action="reset-confirmed">Começar do zero</button>`),'reset');break;
 case 'reset-confirmed':if(state)save();closeModal();try{localStorage.removeItem(KEY);}catch{}state=null;window.saveCorrupted=false;draft.name='';draft.short='';draft.careerGoals=[];draft.rival=D.teams.find(t=>t.id!==draft.slot).id;careerTab='current';captainOptions=E.drawCaptains();draft.captain=captainOptions[0];view='club';render();window.scrollTo(0,0);break;
 }
 }catch(error){toast(error.message||'Não foi possível concluir esta ação.');b.disabled=false;}});
document.addEventListener('input',event=>{const el=event.target;if(el.closest('#legacy-form'))previewLegacy();if(!state){if(el.id==='club-name')draft.name=el.value;if(el.id==='club-short')draft.short=el.value;if(el.name==='primary')draft.color=el.value;if(el.name==='secondary')draft.secondary=el.value;}if(el.id==='album-search'){albumFilters.query=el.value;albumPage=0;refreshAlbum();}if(el.id==='roster-search'){rosterFilter=el.value;$('#roster-cards').innerHTML=rosterCards();}});
document.addEventListener('change',event=>{const el=event.target;if(el.closest('#legacy-form'))previewLegacy();try{switch(el.id){case 'album-status':albumFilters.status=el.value;albumPage=0;refreshAlbum();break;case 'album-rarity':albumFilters.rarity=el.value;albumPage=0;refreshAlbum();break;case 'album-pos':albumFilters.pos=el.value;albumPage=0;refreshAlbum();break;case 'hall-sort':hallSort=el.value;render();break;case 'club-slot':draft.slot=el.value;refreshRivalSetup();break;case 'club-rival':draft.rival=el.value;break;case 'formation':E.changeFormation(state,el.value);save();render();toast('Formação alterada. Titulares e banco reorganizados.');break;case 'captain-select':state.captain=el.value;save();render();break;case 'roster-position':rosterPos=el.value;$('#roster-cards').innerHTML=rosterCards();break;case 'roster-sort':rosterSort=el.value;$('#roster-cards').innerHTML=rosterCards();break;case 'round-select':leagueRound=Number(el.value);render();break;case 'sound-toggle':prefs.sound=el.checked;savePrefs();sound();break;case 'quick-toggle':prefs.quick=el.checked;savePrefs();break;}}catch(e){toast(e.message);}});
document.addEventListener('submit',event=>{if(event.target.id==='legacy-form'){event.preventDefault();try{const next=E.createLegacyReward(legacyProfile,Object.fromEntries(new FormData(event.target)));localStorage.setItem(LEGACY_KEY,JSON.stringify(next));legacyProfile=next;save();closeModal();render();sound('win');toast('Lenda criada! Sua carta acompanha os próximos clubes.');}catch(e){toast(e.message||'Não foi possível salvar a lenda neste navegador.');}return;}if(event.target.id!=='create-form')return;event.preventDefault();const f=new FormData(event.target),name=String(f.get('clubName')).trim();if(name.length<2){toast('Dê um nome de pelo menos duas letras ao clube.');return;}try{state=E.createClub({...draft,legacyCard:legacyProfile.card,name,short:f.get('short'),color:f.get('primary'),secondary:f.get('secondary'),slot:f.get('slot'),rival:f.get('rival')});careerTab='current';E.openPack(state,'welcome');save();view='club';render();showPack('sealed');}catch(e){toast(e.message);}});
modal.addEventListener('cancel',event=>{if(modalType==='simulating-career'){event.preventDefault();return;}if(modalType==='season'){state.autoCareer=false;save();}if(modalType==='pack'||modalType==='match'&&matchTimer){event.preventDefault();if(modalType==='match'){clearInterval(matchTimer);matchTimer=null;showMatch(state.lastMatch);}return;}if(state?.unseenMatch&&modalType==='match'){state.unseenMatch=false;save();}modalType='';});
window.addEventListener('storage',event=>{try{
 if(event.key===BOOK_KEY&&event.newValue){const other=JSON.parse(event.newValue);if(E.validClubBook(other)){clubBook=E.mergeClubBooks(clubBook,other);if(view==='memories'||view==='career')render();}}
 if(event.key===LEGACY_KEY&&event.newValue){syncLegacyProfile();if(!state)refreshGoalSetup();}
 if(event.key===KEY&&event.newValue){const other=JSON.parse(event.newValue);if(E.validate(other)){state=other;E.ensureClubLore(state);legacyProfile=E.unlockLegacyProfile(legacyProfile,state);syncBook();clearInterval(matchTimer);matchTimer=null;closeModal();render();recoverPending();toast('Progresso atualizado pela outra aba.');}}
 }catch{}});
// Optional browser-agent support; ordinary browsers require no extension.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_club_summary',description:'Read the current fantasy football club, season, coins and team strength without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return state?{club:state.club.name,season:state.season,round:state.round,phase:state.phase,coins:state.coins,formation:state.formation,tactic:state.tactic,strength:E.metrics(E.team(state,'user')),players:state.squad.length,pendingPack:Boolean(state.pendingPack)}:{club:null};}});
 register({name:'configure_team',description:'Change formation and tactical plan for the active club, automatically optimize the lineup, save progress and show the squad screen. Does not simulate a match or spend coins.',inputSchema:{type:'object',properties:{formation:{type:'string',enum:Object.keys(D.formations)},tactic:{type:'string',enum:Object.keys(D.tactics)}},required:['formation','tactic'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!state||state.phase==='finished'||state.pendingPack)throw Error('Ajuste indisponível neste momento.');if(!input||!D.formations[input.formation]||!D.tactics[input.tactic]||Object.keys(input).some(k=>!['formation','tactic'].includes(k)))throw Error('Formação ou tática inválida.');E.changeFormation(state,input.formation);state.tactic=input.tactic;save();closeModal();view='squad';squadTab='pitch';render();return {formation:state.formation,tactic:state.tactic,overall:E.metrics(E.team(state,'user')).overall};}});
}
if(state)save();render();recoverPending();
})();
